from typing import List

class Solution:
    def maxAmount(self, initialCurrency: str, pairs1: List[List[str]], rates1: List[float], pairs2: List[List[str]], rates2: List[float]) -> float:
        def build_edges(pairs, rates):
            edges = []
            for (s, t), r in zip(pairs, rates):
                edges.append((s, t, r))
                edges.append((t, s, 1.0 / r))
            return edges

        def best_from(source, edges, nodes):
            # max product path from source to every node
            best = {v: 0.0 for v in nodes}
            best[source] = 1.0
            changed = True
            it = 0
            while changed and it < len(nodes) + 5:
                changed = False
                it += 1
                for u, v, w in edges:
                    if best[u] > 0 and best[u] * w > best[v] + 1e-12:
                        best[v] = best[u] * w
                        changed = True
            return best

        edges1 = build_edges(pairs1, rates1)
        edges2 = build_edges(pairs2, rates2)
        nodes = set([initialCurrency])
        for s, t in pairs1:
            nodes.add(s); nodes.add(t)
        for s, t in pairs2:
            nodes.add(s); nodes.add(t)
        nodes = list(nodes)

        day1 = best_from(initialCurrency, edges1, nodes)

        result = 0.0
        # For each intermediate currency c, compute best factor c -> initial on day 2
        for c in nodes:
            if day1[c] <= 0:
                continue
            f2 = best_from(c, edges2, nodes)
            if f2[initialCurrency] > 0:
                result = max(result, day1[c] * f2[initialCurrency])
        return float(result)
