class Solution:
    def maxAmount(self, initialCurrency: str, pairs1: List[List[str]], rates1: List[float], pairs2: List[List[str]], rates2: List[float]) -> float:
        names = set([initialCurrency])
        for p in pairs1 + pairs2:
            names.add(p[0])
            names.add(p[1])
        idx = {c: i for i, c in enumerate(sorted(names))}
        k = len(idx)

        def build(pairs, rates):
            M = [[0.0] * k for _ in range(k)]
            for i in range(k):
                M[i][i] = 1.0
            for (a, b), r in zip(pairs, rates):
                ia, ib = idx[a], idx[b]
                M[ia][ib] = max(M[ia][ib], r)
                M[ib][ia] = max(M[ib][ia], 1.0 / r)
            for t in range(k):
                for i in range(k):
                    if M[i][t] == 0.0:
                        continue
                    for j in range(k):
                        v = M[i][t] * M[t][j]
                        if v > M[i][j]:
                            M[i][j] = v
            return M

        M1 = build(pairs1, rates1)
        M2 = build(pairs2, rates2)
        s = idx[initialCurrency]
        best = 0.0
        for c in range(k):
            a = M1[s][c]
            b = M2[c][s]
            if a > 0 and b > 0:
                best = max(best, a * b)
        return best

