import json
from hypothesis import strategies as st

NAMES = ["USD", "EUR", "JPY", "CHF", "NGN", "GBP"]


def _best(pairs, rates, src):
    # Enumerate all simple paths (exponential, fine for tiny inputs) and keep
    # the maximum multiplier reaching each currency from src.
    adj = {}
    for (s, t), r in zip(pairs, rates):
        adj.setdefault(s, []).append((t, r))
        adj.setdefault(t, []).append((s, 1.0 / r))
    best = {src: 1.0}

    def dfs(node, val, visited):
        for nxt, mul in adj.get(node, []):
            if nxt in visited:
                continue
            nv = val * mul
            if nxt not in best or nv > best[nxt]:
                best[nxt] = nv
            visited.add(nxt)
            dfs(nxt, nv, visited)
            visited.remove(nxt)

    dfs(src, 1.0, {src})
    return best


def _is_forest(pairs):
    parent = {}

    def find(x):
        parent.setdefault(x, x)
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for s, t in pairs:
        rs, rt = find(s), find(t)
        if rs == rt:
            return False
        parent[rs] = rt
    return True


def _gen_pairs(draw):
    k = draw(st.integers(2, 5))
    nodes = draw(st.permutations(NAMES))[:k]
    pairs, rates = [], []
    for i in range(1, k):
        p = draw(st.integers(0, i - 1))
        r = draw(st.sampled_from([1.0, 2.0, 10.0, 1.5, 3.0, 4.0, 5.0, 6.0, 9.0, 7.5]))
        if draw(st.booleans()):
            pairs.append([nodes[p], nodes[i]])
        else:
            pairs.append([nodes[i], nodes[p]])
        rates.append(r)
    return pairs, rates


@st.composite
def gen(draw):
    init = draw(st.sampled_from(NAMES))
    p1, r1 = _gen_pairs(draw)
    p2, r2 = _gen_pairs(draw)
    return (
        json.dumps(init) + "\n"
        + json.dumps(p1) + "\n"
        + json.dumps(r1) + "\n"
        + json.dumps(p2) + "\n"
        + json.dumps(r2)
    )


def validate(inp):
    lines = inp.split("\n")
    if len(lines) != 5:
        return False
    init = json.loads(lines[0])
    p1 = json.loads(lines[1])
    r1 = json.loads(lines[2])
    p2 = json.loads(lines[3])
    r2 = json.loads(lines[4])
    if not isinstance(init, str) or not (1 <= len(init) <= 3):
        return False
    if not all(c.isupper() and c.isalpha() for c in init):
        return False
    for pairs, rates in ((p1, r1), (p2, r2)):
        if not isinstance(pairs, list) or not isinstance(rates, list):
            return False
        if not (1 <= len(pairs) <= 10) or len(pairs) != len(rates):
            return False
        for pr in pairs:
            if not isinstance(pr, list) or len(pr) != 2:
                return False
            for c in pr:
                if not isinstance(c, str) or not (1 <= len(c) <= 3):
                    return False
                if not all(ch.isupper() and ch.isalpha() for ch in c):
                    return False
        for x in rates:
            if not isinstance(x, (int, float)) or not (1.0 <= x <= 10.0):
                return False
        if not _is_forest([tuple(pr) for pr in pairs]):
            return False
    return True


def ref(inp):
    lines = inp.split("\n")
    init = json.loads(lines[0])
    p1 = [tuple(x) for x in json.loads(lines[1])]
    r1 = [float(x) for x in json.loads(lines[2])]
    p2 = [tuple(x) for x in json.loads(lines[3])]
    r2 = [float(x) for x in json.loads(lines[4])]
    d1 = _best(p1, r1, init)
    ans = 0.0
    for c, v in d1.items():
        w = _best(p2, r2, c)
        if init in w:
            ans = max(ans, v * w[init])
    return json.dumps(ans)


