POOL = ["AAA", "BBB", "CCC", "DDD", "EEE"]


def _draw_day(draw, init):
    k = draw(st.integers(2, 5))
    others = [c for c in POOL if c != init]
    rest = draw(st.lists(st.sampled_from(others), min_size=k - 1, max_size=k - 1, unique=True))
    names = [init] + rest
    pairs = []
    rates = []
    for i in range(1, k):
        parent = draw(st.integers(0, i - 1))
        child = names[i]
        par = names[parent]
        if draw(st.booleans()):
            pairs.append([par, child])
        else:
            pairs.append([child, par])
        rates.append(float(draw(st.integers(1, 10))))
    return pairs, rates


@st.composite
def gen(draw):
    init = draw(st.sampled_from(POOL))
    pairs1, rates1 = _draw_day(draw, init)
    pairs2, rates2 = _draw_day(draw, init)
    lines = [
        json.dumps(init),
        json.dumps(pairs1),
        json.dumps(rates1),
        json.dumps(pairs2),
        json.dumps(rates2),
    ]
    return "\n".join(lines)


