def _adj(pairs, rates):
    adj = {}
    for (s, t), r in zip(pairs, rates):
        r = float(r)
        adj.setdefault(s, []).append((t, r))
        adj.setdefault(t, []).append((s, 1.0 / r))
    return adj


def _best_from(adj, src):
    # Max product over all simple paths from src to every reachable node.
    # Cycles have product 1 (no contradictions), so simple paths suffice.
    best = {}

    def dfs(node, val, visited):
        if node not in best or val > best[node]:
            best[node] = val
        for nxt, r in adj.get(node, []):
            if nxt not in visited:
                dfs(nxt, val * r, visited | {nxt})

    dfs(src, 1.0, frozenset([src]))
    return best


