import json
from hypothesis import strategies as st

POOL = ["EUR", "USD", "JPY", "CHF", "NGN", "GBP", "INR", "AB", "XYZ"]


def _forest_edges(draw, cur):
    # Build a spanning tree over cur (no cycles, no duplicate pairs).
    pairs, rates = [], []
    for i in range(1, len(cur)):
        p = draw(st.integers(0, i - 1))
        a, b = cur[p], cur[i]
        if draw(st.booleans()):
            a, b = b, a
        pairs.append([a, b])
        rates.append(draw(st.integers(10, 100)) / 10.0)
    return pairs, rates


@st.composite
def gen(draw):
    init = draw(st.sampled_from(POOL))
    k1 = draw(st.integers(2, 4))
    cur1 = draw(st.lists(st.sampled_from(POOL), min_size=k1, max_size=k1, unique=True))
    if init not in cur1 and draw(st.booleans()):
        cur1[0] = init
    p1, r1 = _forest_edges(draw, cur1)
    k2 = draw(st.integers(2, 4))
    cur2 = draw(st.lists(st.sampled_from(POOL), min_size=k2, max_size=k2, unique=True))
    if init in cur2 and draw(st.booleans()):
        cur2 = [c for c in cur2]  # keep as is; init may appear in day 2
    p2, r2 = _forest_edges(draw, cur2)
    return (
        json.dumps(init) + "\n"
        + json.dumps(p1) + "\n"
        + json.dumps(r1) + "\n"
        + json.dumps(p2) + "\n"
        + json.dumps(r2) + "\n"
    )


def _check_day(pairs, rates):
    if not (isinstance(pairs, list) and isinstance(rates, list)):
        return False
    if not (1 <= len(pairs) <= 10 and len(rates) == len(pairs)):
        return False
    parent = {}

    def find(x):
        while parent.setdefault(x, x) != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    seen = set()
    for pr, r in zip(pairs, rates):
        if not (isinstance(pr, list) and len(pr) == 2):
            return False
        s, t = pr
        for c in (s, t):
            if not (isinstance(c, str) and 1 <= len(c) <= 3 and all("A" <= ch <= "Z" for ch in c)):
                return False
        if s == t:
            return False
        key = frozenset((s, t))
        if key in seen:
            return False
        seen.add(key)
        if not (isinstance(r, (int, float)) and 1.0 <= float(r) <= 10.0):
            return False
        rs, rt = find(s), find(t)
        if rs == rt:
            return False  # cycle
        parent[rs] = rt
    return True


def _relax(pairs, rates, start):
    vals = {start: 1.0}
    edges = []
    for (s, t), r in zip(pairs, rates):
        edges.append((s, t, float(r)))
        edges.append((t, s, 1.0 / float(r)))
    for _ in range(len(edges) + 5):
        changed = False
        for x, y, f in edges:
            if x in vals:
                v = vals[x] * f
                if y not in vals or v > vals[y] * (1 + 1e-12):
                    vals[y] = v
                    changed = True
        if not changed:
            break
    return vals


def validate(inp):
    try:
        lines = inp.split("\n")
        if len(lines) < 5:
            return False
        init = json.loads(lines[0])
        p1 = json.loads(lines[1])
        r1 = json.loads(lines[2])
        p2 = json.loads(lines[3])
        r2 = json.loads(lines[4])
        if not (isinstance(init, str) and 1 <= len(init) <= 3
                and all("A" <= ch <= "Z" for ch in init)):
            return False
        if not (_check_day(p1, r1) and _check_day(p2, r2)):
            return False
        # Answer must fit the stated bound.
        return _ref_value(init, p1, r1, p2, r2) <= 5 * 10**10
    except Exception:
        return False


def _ref_value(init, p1, r1, p2, r2):
    d1 = _relax(p1, r1, init)
    best = 0.0
    for c, v in d1.items():
        d2 = _relax(p2, r2, c)
        if init in d2:
            best = max(best, v * d2[init])
    return best


def ref(inp):
    lines = inp.split("\n")
    init = json.loads(lines[0])
    p1 = json.loads(lines[1])
    r1 = json.loads(lines[2])
    p2 = json.loads(lines[3])
    r2 = json.loads(lines[4])
    return json.dumps(_ref_value(init, p1, r1, p2, r2))


